import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)
# A comment at the end of a line also takes the whitespace before it (and after it).
TRAILING_COMMENT = re.compile(r"[ \t]*<!--.*?-->[ \t]*(?=\r?\n|\Z)", re.DOTALL)
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    return COMMENT.sub("", TRAILING_COMMENT.sub("", text))


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match:
                current = Release(match.group("version"), match.group("date"))
                releases.append(current)
            else:
                current = None
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    out = []
    for line in lines:
        if not line.strip():
            line = ""
            if not out or out[-1] == "":
                continue
        out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            title = f"{release.version} ({release.date})" if release.date else release.version
            if not release.date:
                title = release.version
            heading = f"# {title}" if release.date else f"# {release.version}"
            body = _clean_body(release.body)
            return f"{heading}\n\n{body}\n"
    raise LookupError(version)
EOF
